// ─── Main component ───────────────────────────────────────────────────────────
const Bookings = () => {
  const navigate = useNavigate()

  const [user, setUser] = useState<bookcarsTypes.User>()
  const [leftPanel, setLeftPanel] = useState(false)
  const [admin, setAdmin] = useState(false)
  const [allSuppliers, setAllSuppliers] = useState<bookcarsTypes.User[]>([])
  const [suppliers, setSuppliers] = useState<string[]>()
  const [statuses, setStatuses] = useState(helper.getBookingStatuses().map((status) => status.value))
  const [filter, setFilter] = useState<bookcarsTypes.Filter | null>()
  const [loadingSuppliers, setLoadingSuppliers] = useState(true)
  const [offset, setOffset] = useState(0)

  // ── Top filter-bar state ──────────────────────────────────────────────────
  const [searchText, setSearchText] = useState('')
  const [dateFrom, setDateFrom] = useState<Date | null>(null)
  const [dateTo, setDateTo] = useState<Date | null>(null)
  const [activeStatusChip, setActiveStatusChip] = useState<string>('all')

  useEffect(() => {
    if (user && user.verified) {
      const col1 = document.querySelector('div.col-1')
      if (col1) {
        setOffset(col1.clientHeight)
      }
    }
  }, [user])

  const handleSupplierFilterChange = (_suppliers: string[]) => {
    setSuppliers(_suppliers)
  }

  const handleStatusFilterChange = (_statuses: bookcarsTypes.BookingStatus[]) => {
    setStatuses(_statuses)
  }

  const handleBookingFilterSubmit = (_filter: bookcarsTypes.Filter | null) => {
    setFilter(_filter)
  }

  const onLoad = async (_user?: bookcarsTypes.User) => {
    if (_user) {
      const _admin = helper.admin(_user)
      setUser(_user)
      setAdmin(_admin)
      setLeftPanel(!_admin)
      setLoadingSuppliers(_admin)

      const _allSuppliers = await SupplierService.getAllSuppliers()
      const _suppliers = _admin ? bookcarsHelper.flattenSuppliers(_allSuppliers) : [_user._id ?? '']
      setAllSuppliers(_allSuppliers)
      setSuppliers(_suppliers)
      setLeftPanel(true)
      setLoadingSuppliers(false)
    }
  }

  // Build a combined filter merging the top-bar with BookingFilter
  const combinedFilter: bookcarsTypes.Filter | null = (() => {
    const base = filter ? { ...filter } : {}
    if (searchText) {
(base as any).keyword = searchText
}
    if (dateFrom) {
(base as any).from = dateFrom
}
    if (dateTo) {
(base as any).to = dateTo
}
    return Object.keys(base).length > 0 ? (base as bookcarsTypes.Filter) : null
  })()

  // Status chip click also updates the sidebar StatusFilter state
  const handleStatusChip = (val: string) => {
    setActiveStatusChip(val)
    if (val === 'all') {
      setStatuses(helper.getBookingStatuses().map((s) => s.value))
    } else {
      setStatuses([val as bookcarsTypes.BookingStatus])
    }
  }

  const columns = buildColumns(navigate)

  return (
    <Layout onLoad={onLoad} strict>
      {user && (
        <Box sx={{ background: CANVAS, minHeight: '100vh' }}>
          {/* ── Top filter bar ── */}
          <Box
            sx={{
              background: CARD_BG,
              borderBottom: `1px solid ${CARD_BORDER}`,
              px: 3,
              py: 1.5,
              display: 'flex',
              flexWrap: 'wrap',
              alignItems: 'center',
              gap: 2,
            }}
          >
            {/* Search */}
            <TextField
              size="small"
              placeholder="Search booking ID or renter…"
              value={searchText}
              onChange={(e) => setSearchText(e.target.value)}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchIcon fontSize="small" />
                  </InputAdornment>
                ),
                sx: { fontFamily: "'Inter', sans-serif", fontSize: 13 },
              }}
              sx={{ minWidth: 230 }}
            />

            {/* Date range */}
            <LocalizationProvider dateAdapter={AdapterDateFns}>
              <DatePicker
                label="Pickup from"
                value={dateFrom}
                onChange={(d) => setDateFrom(d)}
                slotProps={{ textField: { size: 'small', sx: { minWidth: 150 } } }}
              />
              <DatePicker
                label="Return to"
                value={dateTo}
                onChange={(d) => setDateTo(d)}
                slotProps={{ textField: { size: 'small', sx: { minWidth: 150 } } }}
              />
            </LocalizationProvider>

            {/* Status chips */}
            <Stack direction="row" spacing={1} flexWrap="wrap">
              {STATUS_CHIPS.map((chip) => (
                <Chip
                  key={chip.value}
                  label={chip.label}
                  size="small"
                  onClick={() => handleStatusChip(chip.value)}
                  sx={{
                    cursor: 'pointer',
                    fontFamily: "'Inter', sans-serif",
                    fontWeight: activeStatusChip === chip.value ? 700 : 400,
                    background: activeStatusChip === chip.value ? EMERALD : CANVAS,
                    color: activeStatusChip === chip.value ? '#fff' : 'var(--sr-muted)',
                    border: `1px solid ${activeStatusChip === chip.value ? EMERALD : CARD_BORDER}`,
                    '&:hover': { background: activeStatusChip === chip.value ? EMERALD_HOVER : '#E2E8F0' },
                  }}
                />
              ))}
            </Stack>

            {/* New booking button */}
            <Box sx={{ ml: 'auto' }}>
              <Button
                variant="contained"
                size="small"
                onClick={() => navigate('/create-booking')}
                sx={{
                  background: EMERALD,
                  '&:hover': { background: EMERALD_HOVER },
                  fontFamily: "'Plus Jakarta Sans', sans-serif",
                  fontWeight: 600,
                  textTransform: 'none',
                  borderRadius: '8px',
                }}
              >
                {strings.NEW_BOOKING}
              </Button>
            </Box>
          </Box>

          {/* ── Main layout ── */}
          <div className="bookings">
            <div className="col-1">
              {leftPanel && (
                <>
                  {admin && (
                    <SupplierFilter
                      suppliers={allSuppliers}
                      onChange={handleSupplierFilterChange}
                      className="cl-supplier-filter"
                    />
                  )}
                  <StatusFilter
                    onChange={handleStatusFilterChange}
                    className="cl-status-filter"
                  />
                  <BookingFilter
                    onSubmit={handleBookingFilterSubmit}
                    language={(user && user.language) || env.DEFAULT_LANGUAGE}
                    className="cl-booking-filter"
                    collapse={!env.isMobile}
                  />
                </>
              )}
            </div>
            <div className="col-2">
              <BookingList
                containerClassName="bookings"
                offset={offset}
                language={user.language}
                loggedUser={user}
                suppliers={suppliers}
                statuses={statuses}
                filter={combinedFilter}
                loading={loadingSuppliers}
                hideDates={env.isMobile}
                checkboxSelection={!env.isMobile}
              />
            </div>
          </div>
        </Box>
      )}
    </Layout>
  )
}

export default Bookings

import React, { useState } from 'react'
import { Alert, Button, Card, CardContent, MenuItem, Select, TextField, Typography } from '@mui/material'
import Layout from '@/components/Layout'
import * as HandoverService from '@/services/HandoverService'
import * as helper from '@/utils/helper'

const Handover = () => {
  const bookingId = new URLSearchParams(window.location.search).get('booking') || ''
  const [status, setStatus] = useState('scheduled')
  const [odometer, setOdometer] = useState('')
  const [fuel, setFuel] = useState('')
  const [damageNotes, setDamageNotes] = useState('')
  const [odometerReturn, setOdometerReturn] = useState('')
  const [fuelReturn, setFuelReturn] = useState('')
  const [customerSignature, setCustomerSignature] = useState('')
  const [supplierSignature, setSupplierSignature] = useState('')
  const [photos, setPhotos] = useState<string[]>([])
  const [message, setMessage] = useState('')

  const submit = async () => {
    if (!bookingId) {
      setMessage('Open handover from a booking.')
      return
    }
    try {
      let uploadedPhotos = photos
      const input = document.querySelector<HTMLInputElement>('#handover-photos')
      if (input?.files?.length) {
        const result = await HandoverService.uploadPhotos(Array.from(input.files))
        uploadedPhotos = [...uploadedPhotos, ...result.photos]
      }
      await HandoverService.upsert({
        booking: bookingId,
        status: status as 'scheduled' | 'in_progress' | 'completed' | 'cancelled',
        odometerAtPickup: odometer ? Number(odometer) : undefined,
        fuelLevelAtPickup: fuel ? Number(fuel) : undefined,
        checklistAtPickup: { exterior: true, interior: true, documents: true, keys: true },
        odometerAtReturn: odometerReturn ? Number(odometerReturn) : undefined,
        fuelLevelAtReturn: fuelReturn ? Number(fuelReturn) : undefined,
        checklistAtReturn: { exterior: true, interior: true, keys: true, fuel: true },
        pickupPhotos: uploadedPhotos,
        returnPhotos: uploadedPhotos,
        customerSignature,
        supplierSignature,
        damageNotes,
      })
      setMessage('Digital handover checklist saved.')
    } catch (error) {
      helper.error(error)
    }
  }

  return (
    <Layout admin strict>
      <Typography variant="h4">Digital handover</Typography>
      {!bookingId && <Alert severity="warning">Open digital handover from a booking detail page.</Alert>}
      <Card sx={{ mt: 2 }}><CardContent>
        <Select fullWidth value={status} onChange={(event) => setStatus(event.target.value)}>
          <MenuItem value="scheduled">Scheduled</MenuItem>
          <MenuItem value="in_progress">In progress</MenuItem>
          <MenuItem value="completed">Completed</MenuItem>
          <MenuItem value="cancelled">Cancelled</MenuItem>
        </Select>
        <TextField fullWidth sx={{ mt: 2 }} type="number" label="Pickup odometer" value={odometer} onChange={(event) => setOdometer(event.target.value)} />
        <TextField fullWidth sx={{ mt: 2 }} type="number" label="Pickup fuel (%)" value={fuel} onChange={(event) => setFuel(event.target.value)} />
        <TextField fullWidth sx={{ mt: 2 }} type="number" label="Return odometer" value={odometerReturn} onChange={(event) => setOdometerReturn(event.target.value)} />
        <TextField fullWidth sx={{ mt: 2 }} type="number" label="Return fuel (%)" value={fuelReturn} onChange={(event) => setFuelReturn(event.target.value)} />
        <TextField fullWidth sx={{ mt: 2 }} label="Customer signature" value={customerSignature} onChange={(event) => setCustomerSignature(event.target.value)} />
        <TextField fullWidth sx={{ mt: 2 }} label="Supplier signature" value={supplierSignature} onChange={(event) => setSupplierSignature(event.target.value)} />
        <TextField id="handover-photos" fullWidth sx={{ mt: 2 }} type="file" label="Handover photos" InputLabelProps={{ shrink: true }} inputProps={{ accept: 'image/jpeg,image/png,image/webp', multiple: true }} />
        <TextField fullWidth multiline minRows={3} sx={{ mt: 2 }} label="Damage notes" value={damageNotes} onChange={(event) => setDamageNotes(event.target.value)} />
        <Button sx={{ mt: 2 }} variant="contained" className="btn-primary" onClick={submit}>Save handover</Button>
        {message && <Alert sx={{ mt: 2 }} severity="info">{message}</Alert>}
      </CardContent></Card>
    </Layout>
  )
}

export default Handover

import React, { useEffect, useState } from 'react'
import { Alert, Button, Card, CardContent, MenuItem, Select, TextField, Typography } from '@mui/material'
import * as bookcarsTypes from ':bookcars-types'
import Layout from '@/components/Layout'
import * as KycService from '@/services/KycService'
import * as helper from '@/utils/helper'

const Kyc = () => {
  const [rows, setRows] = useState<bookcarsTypes.Kyc[]>([])
  const [reason, setReason] = useState<Record<string, string>>({})

  const load = async () => {
    try {
      setRows(await KycService.getPending())
    } catch (error) {
      helper.error(error)
    }
  }

  useEffect(() => {
    load()
  }, [])

  const review = async (row: bookcarsTypes.Kyc, status: 'approved' | 'rejected' | 'suspended') => {
    try {
      await KycService.review(row._id!, status, reason[row._id!])
      await load()
    } catch (error) {
      helper.error(error)
    }
  }

  return (
    <Layout admin strict>
      <Typography variant="h4">CNIC & KYC review</Typography>
      {rows.length === 0 && <Alert severity="info">No pending KYC submissions.</Alert>}
      {rows.map((row) => (
        <Card key={row._id} sx={{ mt: 2 }}>
          <CardContent>
            <Typography variant="h6">{row.documentType.toUpperCase()} — {row.documentNumber}</Typography>
            <Typography>Status: {row.status}</Typography>
            <TextField
              fullWidth
              label="Rejection reason"
              value={reason[row._id!] || ''}
              onChange={(event) => setReason((current) => ({ ...current, [row._id!]: event.target.value }))}
              sx={{ my: 1 }}
            />
            <Button variant="contained" className="btn-primary" onClick={() => review(row, 'approved')}>Approve</Button>
            <Button variant="outlined" color="error" sx={{ ml: 1 }} onClick={() => review(row, 'rejected')}>Reject</Button>
            <Button variant="outlined" color="warning" sx={{ ml: 1 }} onClick={() => review(row, 'suspended')}>Suspend</Button>
          </CardContent>
        </Card>
      ))}
    </Layout>
  )
}

export default Kyc

import React, { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import {
  Typography,
  IconButton,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Tooltip,
  Link,
  Chip,
  Box,
  Grid,
  Avatar as MuiAvatar,
  Divider,
  Stack,
} from '@mui/material'
import {
  Edit as EditIcon,
  Delete as DeleteIcon,
  DirectionsCar as CarIcon,
  VerifiedUser as VerifiedIcon,
  GppMaybe as UnverifiedIcon,
  Person as PersonIcon,
} from '@mui/icons-material'
import * as bookcarsTypes from ':bookcars-types'
import * as bookcarsHelper from ':bookcars-helper'
import env from '@/config/env.config'
import { strings as commonStrings } from '@/lang/common'
import { strings as ulStrings } from '@/lang/user-list'
import * as UserService from '@/services/UserService'
import * as helper from '@/utils/helper'
import Layout from '@/components/Layout'
import Backdrop from '@/components/SimpleBackdrop'
import Avatar from '@/components/Avatar'
import BookingList from '@/components/BookingList'
import NoMatch from './NoMatch'
import * as SupplierService from '@/services/SupplierService'

import '@/assets/css/user.css'

// ── Design tokens ──────────────────────────────────────────────
const EMERALD = '#107487'
const GOLD = '#995000'
const OBSIDIAN = '#0F172A'
const CRIMSON = '#DC2626'
const CANVAS = 'var(--sr-ink)'

const cardStyle = {
  backgroundColor: 'var(--sr-surface)',
  borderRadius: '16px',
  border: '1px solid #E2E8F0',
  padding: '24px',
}

const sectionHeaderSx = {
  color: 'var(--sr-emerald)',
  fontWeight: 600,
  fontSize: 13,
  textTransform: 'uppercase' as const,
  letterSpacing: '0.08em',
  mb: 2,
}

const monoFont = { fontFamily: '"JetBrains Mono", "Fira Mono", monospace' }

const getRoleBadge = (type?: string) => {
  if (type === bookcarsTypes.RecordType.Admin) {
return { label: 'Admin', bg: OBSIDIAN, color: '#fff' }
}
  if (type === bookcarsTypes.RecordType.Supplier) {
return { label: 'Supplier', bg: GOLD, color: '#fff' }
}
  return { label: 'Customer', bg: EMERALD, color: '#fff' }
}

const maskCnic = (cnic?: string) => {
  if (!cnic) {
return 'XXXXX-XXXXXXX-X'
}
  const digits = cnic.replace(/\D/g, '')
  if (digits.length !== 13) {
return cnic
}
  return `${digits.slice(0, 5)}-${digits.slice(5, 12)}-${digits.slice(12)}`
}

const User = () => {
  const navigate = useNavigate()

  const statuses = helper.getBookingStatuses().map((status) => status.value)

  const [loggedUser, setLoggedUser] = useState<bookcarsTypes.User>()
  const [user, setUser] = useState<bookcarsTypes.User>()
  const [visible, setVisible] = useState(false)
  const [loading, setLoading] = useState(true)
  const [noMatch, setNoMatch] = useState(false)
  const [openDeleteDialog, setOpenDeleteDialog] = useState(false)
  const [suppliers, setSuppliers] = useState<string[]>([])
  const [offset, setOffset] = useState(0)
  const [kycSaving, setKycSaving] = useState(false)

  const setKycStatus = async (status: bookcarsTypes.KycStatus) => {
    if (!user?._id) {
return
}
    setKycSaving(true)
    try {
      const result = await UserService.updateKycStatus(user._id, status)
      setUser({ ...user, kycStatus: result.kycStatus })
      helper.info(`KYC status set to ${result.kycStatus}.`)
    } catch (err) {
      helper.error(err)
    } finally {
      setKycSaving(false)
    }
  }

  useEffect(() => {
    if (visible) {
      const col1 = document.querySelector('.col-1')
      if (col1) {
        setOffset(col1.clientHeight)
      }
    }
  }, [visible])

  const onBeforeUpload = () => {
    setLoading(true)
  }

  const onAvatarChange = () => {
    setLoading(false)
  }

  const handleDelete = () => {
    setOpenDeleteDialog(true)
  }

  const handleConfirmDelete = async () => {
    try {
      if (user) {
        setOpenDeleteDialog(false)

        const status = await UserService.deleteUsers([user._id as string])

        if (status === 200) {
          navigate('/users')
        } else {
          helper.error()
          setLoading(false)
        }
      } else {
        helper.error()
      }
    } catch (err) {
      helper.error(err)
    }
  }

  const handleCancelDelete = () => {
    setOpenDeleteDialog(false)
  }

  const onLoad = async (_loggedUser?: bookcarsTypes.User) => {
    if (_loggedUser && _loggedUser.verified) {
      setLoading(true)

      const params = new URLSearchParams(window.location.search)
      if (params.has('u')) {
        const id = params.get('u')
        if (id && id !== '') {
          try {
            const _user = await UserService.getUser(id)

            if (_user) {
              const setState = (_suppliers: string[]) => {
                setSuppliers(_suppliers)
                setLoggedUser(_loggedUser)
                setUser(_user)
                setVisible(true)
                setLoading(false)
              }

              const admin = helper.admin(_loggedUser)
              if (admin) {
                const _suppliers = await SupplierService.getAllSuppliers()
                const supplierIds = bookcarsHelper.flattenSuppliers(_suppliers)
                setState(supplierIds)
              } else {
                setState([_loggedUser._id as string])
              }
            } else {
              setLoading(false)
              setNoMatch(true)
            }
          } catch (err) {
            helper.error(err)
            setLoading(false)
            setVisible(false)
          }
        } else {
          setLoading(false)
          setNoMatch(true)
        }
      } else {
        setLoading(false)
        setNoMatch(true)
      }
    }
  }

  const edit = loggedUser && user && (loggedUser.type === bookcarsTypes.RecordType.Admin || loggedUser._id === user._id || (loggedUser.type === bookcarsTypes.RecordType.Supplier && loggedUser._id === user.supplier))
  const supplier = user && user.type === bookcarsTypes.RecordType.Supplier

  let _suppliers: string[] = []
  if (loggedUser && user) {
    if ((supplier && loggedUser._id === user._id)
      || (loggedUser.type === bookcarsTypes.RecordType.Admin && user.type === bookcarsTypes.RecordType.Supplier)
    ) {
      _suppliers = [user._id as string]
    } else if (loggedUser.type === bookcarsTypes.RecordType.Supplier && user.type === bookcarsTypes.RecordType.User) {
      _suppliers = [loggedUser._id as string]
    } else if (loggedUser.type === bookcarsTypes.RecordType.Admin) {
      _suppliers = suppliers
    }
  }

  const roleBadge = getRoleBadge(user?.type)
  const kycVerified = user?.kycStatus === bookcarsTypes.KycStatus.Verified

  return (
    <Layout onLoad={onLoad} strict>
      {loggedUser && user && visible && (
        <Box sx={{ background: CANVAS, minHeight: '100vh', p: { xs: 2, md: 3 } }}>
          {/* Profile Header */}
          <Typography variant="h5" sx={{ fontWeight: 700, color: 'var(--sr-text)', mb: 3, fontFamily: 'Plus Jakarta Sans, sans-serif' }}>
            User Profile
          </Typography>

          {/* 2-column profile card */}
          <Grid container spacing={3} sx={{ mb: 3 }}>
            {/* Left column – identity */}
            <Grid size={{ xs: 12, md: 4 }}>
              <Box sx={{ ...cardStyle, display: 'flex', flexDirection: 'column', alignItems: 'center', textAlign: 'center', gap: 1 }}>
                {/* Avatar 80px */}
                  <Box sx={{ width: 80, height: 80, borderRadius: '50%', overflow: 'hidden', border: `3px solid ${EMERALD}`, flexShrink: 0, display: 'grid', placeItems: 'center', '& .MuiSvgIcon-root': { width: '48px !important', height: '48px !important', color: 'var(--sr-muted)' }, '& img, & .MuiAvatar-root': { width: '74px !important', height: '74px !important', objectFit: 'cover' } }}>
                  <Avatar
                    record={user}
                    type={user.type}
                    mode="update"
                    size="large"
                    hideDelete
                    onBeforeUpload={onBeforeUpload}
                    onChange={onAvatarChange}
                    color="disabled"
                    className={supplier ? 'supplier-avatar' : 'user-avatar'}
                    readonly
                    verified
                  />
                </Box>

                {/* Name */}
                <Typography variant="h6" sx={{ fontWeight: 700, color: 'var(--sr-text)', mt: 1 }}>
                  {user.fullName}
                </Typography>

                {/* Role badge */}
                <Chip
                  label={roleBadge.label}
                  size="small"
                  sx={{ background: roleBadge.bg, color: roleBadge.color, fontWeight: 700, fontSize: 11 }}
                />

                {/* Joined date */}
                {(user as any).createdAt && (
                  <Typography variant="caption" sx={{ color: 'var(--sr-muted)' }}>
                    Joined {new Date((user as any).createdAt).toLocaleDateString('en-PK', { year: 'numeric', month: 'short', day: 'numeric' })}
                  </Typography>
                )}

                {/* Bio/location */}
                {user.bio && (
                  <Typography variant="body2" sx={{ color: 'var(--sr-muted)', mt: 1 }}>{user.bio}</Typography>
                )}
                {user.location && (
                  <Typography variant="body2" sx={{ color: 'var(--sr-muted)' }}>📍 {user.location}</Typography>
                )}

                <Divider sx={{ width: '100%', my: 1.5 }} />

                {/* Action buttons */}
                <Stack direction="row" spacing={1} justifyContent="center">
                  {edit && (
                    <Tooltip title={commonStrings.UPDATE}>
                      <IconButton
                        onClick={() => navigate(`/update-user?u=${user._id}`)}
                        sx={{ backgroundColor: 'var(--sr-surface-raised)', color: 'var(--sr-emerald)', '&:hover': { background: 'var(--sr-emerald-soft)' } }}
                      >
                        <EditIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                  )}
                  {edit && (
                    <Tooltip title={commonStrings.DELETE}>
                      <IconButton
                        data-id={user._id}
                        onClick={handleDelete}
                        sx={{ background: '#FEF2F2', color: CRIMSON, '&:hover': { background: 'var(--sr-surface-raised)' } }}
                      >
                        <DeleteIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                  )}
                  <Tooltip title="View Bookings">
                    <IconButton
                      sx={{ background: '#EFF6FF', color: '#3B82F6', '&:hover': { background: '#DBEAFE' } }}
                    >
                      <CarIcon fontSize="small" />
                    </IconButton>
                  </Tooltip>
                </Stack>
              </Box>
            </Grid>

            {/* Right column – details */}
            <Grid size={{ xs: 12, md: 8 }}>
              <Box sx={cardStyle}>
                <Typography sx={sectionHeaderSx}>Account Details</Typography>

                <Grid container spacing={2}>
                  {/* Email */}
                  <Grid size={{ xs: 12, sm: 6 }}>
                    <Typography variant="caption" sx={{ color: 'var(--sr-muted)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.06em' }}>Email</Typography>
                    <Typography variant="body2" sx={{ color: 'var(--sr-text)', mt: 0.5 }}>{user.email}</Typography>
                  </Grid>

                  {/* Phone */}
                  {user.phone && (
                    <Grid size={{ xs: 12, sm: 6 }}>
                      <Typography variant="caption" sx={{ color: 'var(--sr-muted)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.06em' }}>Phone</Typography>
                      <Typography variant="body2" sx={{ color: 'var(--sr-text)', mt: 0.5 }}>{user.phone}</Typography>
                    </Grid>
                  )}

                  {/* CNIC – JetBrains Mono masked */}
                  {user.type === bookcarsTypes.RecordType.User && (
                    <Grid size={{ xs: 12, sm: 6 }}>
                      <Typography variant="caption" sx={{ color: 'var(--sr-muted)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.06em' }}>CNIC</Typography>
                      <Typography variant="body2" sx={{ ...monoFont, color: 'var(--sr-text)', mt: 0.5, fontSize: 13 }}>
                        {maskCnic(user.cnicNumber)}
                      </Typography>
                    </Grid>
                  )}

                  {/* KYC Status chip */}
                  {user.type === bookcarsTypes.RecordType.User && (
                    <Grid size={{ xs: 12, sm: 6 }}>
                      <Typography variant="caption" sx={{ color: 'var(--sr-muted)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.06em' }}>KYC Status</Typography>
                      <Box sx={{ mt: 0.5 }}>
                        <Chip
                          icon={kycVerified ? <VerifiedIcon sx={{ fontSize: 14 }} /> : <UnverifiedIcon sx={{ fontSize: 14 }} />}
                          label={kycVerified ? 'Verified ✓' : user.kycStatus || 'Unverified'}
                          size="small"
                          sx={{
                            background: kycVerified ? 'var(--sr-emerald-soft)' : 'var(--sr-gold-soft)',
                            color: kycVerified ? 'var(--sr-emerald)' : 'var(--sr-accent-text)',
                            fontWeight: 700,
                            fontSize: 11,
                            '& .MuiChip-icon': { color: kycVerified ? 'var(--sr-emerald)' : 'var(--sr-accent-text)' },
                          }}
                        />
                      </Box>
                    </Grid>
                  )}

                  {/* License */}
                  {user.license && (
                    <Grid size={{ xs: 12, sm: 6 }}>
                      <Typography variant="caption" sx={{ color: 'var(--sr-muted)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.06em' }}>Driving License</Typography>
                      <Box sx={{ mt: 0.5 }}>
                        <Chip
                          label="License ✓"
                          size="small"
                          sx={{ background: 'var(--sr-emerald-soft)', color: 'var(--sr-emerald)', fontWeight: 700, fontSize: 11 }}
                        />
                        <Box sx={{ mt: 0.5 }}>
                          <Link href={bookcarsHelper.joinURL(env.CDN_LICENSES, user.license)} target="_blank" sx={{ fontSize: 12, color: 'var(--sr-emerald)' }}>
                            {commonStrings.LICENSE}
                          </Link>
                        </Box>
                      </Box>
                    </Grid>
                  )}
                </Grid>

                {/* KYC section for User type */}
                {user.type === bookcarsTypes.RecordType.User && (
                  <Box sx={{ mt: 3, pt: 2, borderTop: '1px solid #E2E8F0' }}>
                    <Typography sx={sectionHeaderSx}>KYC Verification</Typography>
                    <Typography variant="body2" sx={{ color: 'var(--sr-muted)', mb: 1 }}>
                      Driving License No: <span style={{ ...monoFont, fontSize: 13 }}>{user.drivingLicenseNumber || 'Not provided'}</span>
                    </Typography>

                    {loggedUser.type === bookcarsTypes.RecordType.Admin && (
                      <Stack direction="row" spacing={1} flexWrap="wrap">
                        <Button
                          size="small"
                          disabled={kycSaving}
                          onClick={() => setKycStatus(bookcarsTypes.KycStatus.Pending)}
                          sx={{ borderRadius: 2, textTransform: 'none', background: 'var(--sr-gold-soft)', color: 'var(--sr-accent-text)', fontWeight: 600, '&:hover': { background: '#FDE68A' } }}
                        >
                          Mark Pending
                        </Button>
                        <Button
                          size="small"
                          disabled={kycSaving}
                          onClick={() => setKycStatus(bookcarsTypes.KycStatus.Verified)}
                          sx={{ borderRadius: 2, textTransform: 'none', background: 'var(--sr-emerald-soft)', color: 'var(--sr-emerald)', fontWeight: 600, '&:hover': { background: '#A7F3D0' } }}
                        >
                          Verify ✓
                        </Button>
                        <Button
                          size="small"
                          color="error"
                          disabled={kycSaving}
                          onClick={() => setKycStatus(bookcarsTypes.KycStatus.Rejected)}
                          sx={{ borderRadius: 2, textTransform: 'none', background: 'var(--sr-surface-raised)', color: CRIMSON, fontWeight: 600, '&:hover': { background: '#FECACA' } }}
                        >
                          Reject
                        </Button>
                      </Stack>
                    )}
                  </Box>
                )}
              </Box>
            </Grid>
          </Grid>

          {/* Bookings section */}
          <Box sx={cardStyle}>
            <Typography sx={sectionHeaderSx}>Bookings</Typography>
            {_suppliers.length > 0 && (
              <BookingList
                containerClassName="user"
                offset={offset}
                loggedUser={loggedUser}
                user={supplier ? undefined : user}
                suppliers={_suppliers}
                statuses={statuses}
                hideDates={env.isMobile}
                checkboxSelection={!env.isMobile}
                hideSupplierColumn={supplier}
                language={loggedUser.language}
              />
            )}
          </Box>
        </Box>
      )}

      <Dialog disableEscapeKeyDown maxWidth="xs" open={openDeleteDialog}>
        <DialogTitle className="dialog-header">{commonStrings.CONFIRM_TITLE}</DialogTitle>
        <DialogContent>{ulStrings.DELETE_USER}</DialogContent>
        <DialogActions className="dialog-actions">
          <Button onClick={handleCancelDelete} variant="contained" className="btn-secondary">
            {commonStrings.CANCEL}
          </Button>
          <Button onClick={handleConfirmDelete} variant="contained" color="error">
            {commonStrings.DELETE}
          </Button>
        </DialogActions>
      </Dialog>

      {loading && <Backdrop text={commonStrings.LOADING} />}
      {noMatch && <NoMatch hideHeader />}
    </Layout>
  )
}

export default User

import React, { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { Button, Chip, Box, TextField, InputAdornment, Stack, Typography } from '@mui/material'
import { Search as SearchIcon, PersonAdd as PersonAddIcon } from '@mui/icons-material'
import * as bookcarsTypes from ':bookcars-types'
import Layout from '@/components/Layout'
import env from '@/config/env.config'
import { strings } from '@/lang/users'
import * as helper from '@/utils/helper'
import UserTypeFilter from '@/components/UserTypeFilter'
import Search from '@/components/Search'
import UserList from '@/components/UserList'

import '@/assets/css/users.css'

// ── Design tokens ──────────────────────────────────────────────
const EMERALD = '#107487'
const GOLD = '#995000'
const OBSIDIAN = '#0F172A'
const CANVAS = 'var(--sr-ink)'

const sectionHeader: React.CSSProperties = {
  color: 'var(--sr-emerald)',
  fontWeight: 600,
  fontSize: 13,
  textTransform: 'uppercase',
  letterSpacing: '0.08em',
}

const cardStyle: React.CSSProperties = {
  backgroundColor: 'var(--sr-surface)',
  borderRadius: '16px',
  border: '1px solid var(--sr-border)',
  padding: '24px',
}

const KYC_FILTER_OPTIONS = [
  { label: 'Verified ✓', value: 'verified' },
  { label: 'Unverified', value: 'unverified' },
]

const ROLE_FILTER_OPTIONS = [
  { label: 'All', value: '' },
  { label: 'Admin', value: bookcarsTypes.UserType.Admin },
  { label: 'Supplier', value: bookcarsTypes.UserType.Supplier },
  { label: 'Customer', value: bookcarsTypes.UserType.User },
]

const Users = () => {
  const navigate = useNavigate()

  const [user, setUser] = useState<bookcarsTypes.User>()
  const [admin, setAdmin] = useState(false)
  const [types, setTypes] = useState<bookcarsTypes.UserType[]>()
  const [keyword, setKeyword] = useState('')
  const [roleFilter, setRoleFilter] = useState('')
  const [kycFilter, setKycFilter] = useState('')

  const handleUserTypeFilterChange = (newTypes: bookcarsTypes.UserType[]) => {
    setTypes(newTypes)
  }

  const handleSearch = (newKeyword: string) => {
    setKeyword(newKeyword)
  }

  const onLoad = (_user?: bookcarsTypes.User) => {
    const _admin = helper.admin(_user)
    const _types = _admin
      ? helper.getUserTypes().map((userType) => userType.value)
      : [bookcarsTypes.UserType.Supplier, bookcarsTypes.UserType.User]

    setUser(_user)
    setAdmin(_admin)
    setTypes(_types)
  }

  const roleBadgeColor = (role: string) => {
    if (role === bookcarsTypes.UserType.Admin) {
return OBSIDIAN
}
    if (role === bookcarsTypes.UserType.Supplier) {
return GOLD
}
    return EMERALD
  }

  return (
    <Layout onLoad={onLoad} strict>
      {user && (
        <Box sx={{ background: CANVAS, minHeight: '100vh', p: { xs: 2, md: 3 } }}>
          {/* Page Header */}
          <Box sx={{ mb: 3, display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 2 }}>
            <Typography variant="h5" sx={{ fontWeight: 700, color: 'var(--sr-text)', fontFamily: 'Plus Jakarta Sans, sans-serif' }}>
              Users
            </Typography>
            <Button
              variant="contained"
              size="small"
              startIcon={<PersonAddIcon />}
              onClick={() => navigate('/create-user')}
              sx={{
                background: EMERALD,
                borderRadius: 2,
                fontWeight: 600,
                textTransform: 'none',
                px: 2.5,
                '&:hover': { background: '#047857' },
              }}
            >
              {strings.NEW_USER}
            </Button>
          </Box>

          {/* Filter Bar Card */}
          <Box sx={{ ...cardStyle, mb: 3 }}>
            <Typography sx={{ ...sectionHeader, mb: 2 }}>Search & Filter</Typography>

            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} useFlexGap alignItems={{ sm: 'center' }} flexWrap={{ xs: 'nowrap', sm: 'wrap' }}>
              {/* Search */}
              <TextField
                placeholder="Search by name, email, or CNIC…"
                size="small"
                value={keyword}
                onChange={(e) => setKeyword(e.target.value)}
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon sx={{ color: 'var(--sr-muted)', fontSize: 18 }} />
                    </InputAdornment>
                  ),
                }}
                sx={{
                  flex: 1,
                  minWidth: { xs: 0, sm: 240 },
                  '& .MuiOutlinedInput-root': { borderRadius: 2, fontSize: 14 },
                }}
              />

              {/* Role Filter Chips */}
              <Stack direction="row" spacing={1} useFlexGap flexWrap="wrap">
                {ROLE_FILTER_OPTIONS.map((opt) => (
                  <Chip
                    key={opt.value}
                    label={opt.label}
                    size="small"
                    onClick={() => {
                      setRoleFilter(opt.value)
                      if (opt.value === '') {
                        const allTypes = helper.getUserTypes().map((ut) => ut.value)
                        setTypes(allTypes)
                      } else {
                        setTypes([opt.value as bookcarsTypes.UserType])
                      }
                    }}
                    sx={{
                      cursor: 'pointer',
                      fontWeight: 600,
                      fontSize: 12,
                      borderRadius: '20px',
                      border: roleFilter === opt.value ? 'none' : '1px solid #E2E8F0',
                      background: roleFilter === opt.value ? roleBadgeColor(opt.value) || OBSIDIAN : 'var(--sr-surface-raised)',
                      color: roleFilter === opt.value ? '#fff' : 'var(--sr-muted)',
                      '&:hover': {
                        background: roleFilter === opt.value ? roleBadgeColor(opt.value) || OBSIDIAN : '#E2E8F0',
                      },
                    }}
                  />
                ))}
              </Stack>

              {/* KYC Status Filter */}
              <Stack direction="row" spacing={1}>
                {KYC_FILTER_OPTIONS.map((opt) => (
                  <Chip
                    key={opt.value}
                    label={opt.label}
                    size="small"
                    onClick={() => setKycFilter(kycFilter === opt.value ? '' : opt.value)}
                    sx={{
                      cursor: 'pointer',
                      fontWeight: 600,
                      fontSize: 12,
                      borderRadius: '20px',
                      border: kycFilter === opt.value ? 'none' : '1px solid #E2E8F0',
                      background: kycFilter === opt.value ? (opt.value === 'verified' ? EMERALD : GOLD) : 'var(--sr-surface-raised)',
                      color: kycFilter === opt.value ? '#fff' : 'var(--sr-muted)',
                      '&:hover': {
                        background: kycFilter === opt.value
                          ? opt.value === 'verified' ? EMERALD : GOLD
                          : '#E2E8F0',
                      },
                    }}
                  />
                ))}
              </Stack>
            </Stack>

            {/* Hidden legacy UserTypeFilter for state sync when admin */}
            {admin && (
              <Box sx={{ display: 'none' }}>
                <UserTypeFilter
                  className="user-type-filter"
                  onChange={handleUserTypeFilterChange}
                />
              </Box>
            )}
          </Box>

          {/* User List Card */}
          <Box sx={{ ...cardStyle, p: 0, overflow: 'hidden' }}>
            <UserList
              user={user}
              types={types}
              keyword={keyword}
              checkboxSelection={!env.isMobile && admin}
              hideDesktopColumns={env.isMobile}
            />
          </Box>
        </Box>
      )}
    </Layout>
  )
}

export default Users

import React, { useCallback, useEffect, useState } from 'react'
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  TextField,
  Typography
} from '@mui/material'
import {
  FolderShared as DocIcon,
  VerifiedUser as VerifiedIcon,
  WarningAmber as WarningIcon,
  DirectionsCar as CarIcon
} from '@mui/icons-material'
import * as bookcarsTypes from ':bookcars-types'
import Layout from '@/components/Layout'
import * as CarService from '@/services/CarService'
import * as VehicleDocumentService from '@/services/VehicleDocumentService'
import * as helper from '@/utils/helper'
import { parseKarachiDate } from '@/utils/timezone'

const labels: Record<bookcarsTypes.VehicleDocumentType, string> = {
  registration: 'Registration / Smart Card',
  insurance: 'Insurance Policy',
  token_tax: 'Token Tax Certificate',
  fitness_certificate: 'Fitness Certificate',
  driver_license: 'Driver License',
}

const VehicleDocuments = () => {
  const vehicleId = new URLSearchParams(window.location.search).get('cr')
  const [vehicle, setVehicle] = useState<bookcarsTypes.Car>()
  const [rows, setRows] = useState<bookcarsTypes.VehicleDocument[]>([])
  const [type, setType] = useState<bookcarsTypes.VehicleDocumentType>('registration')
  const [expiryDate, setExpiryDate] = useState('')
  const [status, setStatus] = useState<bookcarsTypes.VehicleDocumentStatus>('pending')
  const [notes, setNotes] = useState('')
  const [message, setMessage] = useState('')

  const load = useCallback(async () => {
    if (!vehicleId) {
return
}
    try {
      const [car, documents] = await Promise.all([CarService.getCar(vehicleId), VehicleDocumentService.getByVehicle(vehicleId)])
      setVehicle(car)
      setRows(documents)
    } catch (error) {
      helper.error(error)
    }
  }, [vehicleId])

  useEffect(() => {
 load() 
}, [load])

  const submit = async (event: React.FormEvent) => {
    event.preventDefault()
    if (!vehicleId || !expiryDate) {
      setMessage('Vehicle and expiry date are required.')
      return
    }
    try {
      await VehicleDocumentService.upsert({ vehicle: vehicleId, type, status, expiryDate: parseKarachiDate(expiryDate), notes })
      setMessage('Vehicle document saved.')
      await load()
    } catch (error) {
      helper.error(error)
    }
  }

  return (
    <Layout admin strict>
      <div className="maintenance-page" style={{ maxWidth: 1200, margin: '0 auto', padding: '24px 20px 48px' }}>
        {/* Header */}
        <Box sx={{ mb: 3 }}>
          <span className="operations-eyebrow" style={{ color: 'var(--sr-emerald)', fontWeight: 800, fontSize: 11, letterSpacing: '0.1em' }}>
            SAFARRENT • VEHICLE COMPLIANCE VAULT
          </span>
          <Typography variant="h4" sx={{ fontWeight: 800, color: 'var(--sr-text, #0F172A)', letterSpacing: '-0.02em', mt: 0.5, mb: 0.5 }}>
            Smart Card & Tax Vault
          </Typography>
          {vehicle ? (
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, mt: 1 }}>
              <Chip
                icon={<CarIcon fontSize="small" />}
                label={vehicle.name}
                sx={{ fontWeight: 700, bgcolor: 'rgba(5, 150, 105, 0.1)', color: 'var(--sr-emerald)' }}
              />
              {vehicle.licensePlate && (
                <Chip
                  label={vehicle.licensePlate}
                  variant="outlined"
                  sx={{ fontWeight: 800, fontFamily: 'var(--sr-font-mono, monospace)', letterSpacing: '0.06em' }}
                />
              )}
            </Box>
          ) : (
            <Typography color="text.secondary">Upload and audit vehicle registration, token tax, and fitness documents.</Typography>
          )}
        </Box>

        {!vehicleId && <Alert severity="warning" sx={{ mb: 3 }}>Select a vehicle from the Vehicle Fleet list to manage its documents.</Alert>}

        <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', lg: '420px 1fr' }, gap: 3 }}>
          {/* Left Column: Form */}
          <Card sx={{ borderRadius: '14px', border: '1px solid var(--sr-border, #E2E8F0)', height: 'fit-content' }}>
            <CardContent sx={{ p: 3 }}>
              <Typography variant="h6" sx={{ fontWeight: 700, mb: 2, display: 'flex', alignItems: 'center', gap: 1 }}>
                <DocIcon fontSize="small" sx={{ color: 'var(--sr-emerald)' }} /> Record Document
              </Typography>
              <form onSubmit={submit} className="maintenance-form" style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
                <FormControl fullWidth size="small">
                  <InputLabel>Document type</InputLabel>
                  <Select value={type} label="Document type" onChange={(event) => setType(event.target.value as bookcarsTypes.VehicleDocumentType)}>
                    {Object.entries(labels).map(([value, label]) => <MenuItem value={value} key={value}>{label}</MenuItem>)}
                  </Select>
                </FormControl>
                <TextField
                  fullWidth
                  size="small"
                  type="date"
                  label="Expiry date"
                  InputLabelProps={{ shrink: true }}
                  value={expiryDate}
                  onChange={(event) => setExpiryDate(event.target.value)}
                />
                <FormControl fullWidth size="small">
                  <InputLabel>Verification status</InputLabel>
                  <Select value={status} label="Verification status" onChange={(event) => setStatus(event.target.value as bookcarsTypes.VehicleDocumentStatus)}>
                    <MenuItem value="pending">Pending Audit</MenuItem>
                    <MenuItem value="verified">Verified Official</MenuItem>
                    <MenuItem value="expired">Expired / Renewal Due</MenuItem>
                  </Select>
                </FormControl>
                <TextField
                  fullWidth
                  size="small"
                  label="Notes / Excise Verification ID"
                  value={notes}
                  onChange={(event) => setNotes(event.target.value)}
                />
                <Button
                  type="submit"
                  variant="contained"
                  className="btn-primary"
                  disabled={!vehicleId}
                  sx={{
                    bgcolor: '#107487',
                    '&:hover': { bgcolor: '#047857' },
                    py: 1,
                    fontWeight: 700,
                    textTransform: 'none',
                    borderRadius: '8px'
                  }}
                >
                  Save Document
                </Button>
              </form>
              {message && <Alert severity="info" sx={{ mt: 2 }}>{message}</Alert>}
            </CardContent>
          </Card>

          {/* Right Column: Expiry Tracking Cards */}
          <Card sx={{ borderRadius: '14px', border: '1px solid var(--sr-border, #E2E8F0)' }}>
            <CardContent sx={{ p: 3 }}>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2.5 }}>
                <Typography variant="h6" sx={{ fontWeight: 700, display: 'flex', alignItems: 'center', gap: 1 }}>
                  <VerifiedIcon fontSize="small" sx={{ color: 'var(--sr-emerald)' }} /> Document Expiry Tracking
                </Typography>
                <Chip
                  label={`${rows.length} Registered`}
                  size="small"
                  sx={{ fontFamily: 'var(--sr-font-mono, monospace)', fontWeight: 700 }}
                />
              </Box>

              {rows.length === 0 ? (
                <Box sx={{ p: 4, textAlign: 'center', bgcolor: 'rgba(0,0,0,0.02)', borderRadius: '10px' }}>
                  <Typography color="text.secondary">No compliance documents recorded for this vehicle.</Typography>
                </Box>
              ) : (
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                  {rows.map((row) => {
                    const expiry = new Date(row.expiryDate)
                    const days = Math.ceil((expiry.getTime() - Date.now()) / 86400000)
                    const isExpired = days < 0
                    const isExpiringSoon = days >= 0 && days <= 30
                    const countdownLabel = isExpired ? 'Expired 🛑' : isExpiringSoon ? `${days}d remaining ⚠️` : `${days}d valid ✓`
                    const countdownColor = isExpired ? '#DC2626' : isExpiringSoon ? '#D97706' : '#059669'
                    const countdownBg = isExpired ? 'rgba(220, 38, 38, 0.1)' : isExpiringSoon ? 'rgba(217, 119, 6, 0.1)' : 'rgba(5, 150, 105, 0.1)'
                    const countdownBorder = isExpired ? 'rgba(220, 38, 38, 0.3)' : isExpiringSoon ? 'rgba(217, 119, 6, 0.3)' : 'rgba(5, 150, 105, 0.3)'

                    return (
                      <Box
                        key={row._id}
                        sx={{
                          p: 2,
                          borderRadius: '10px',
                          border: '1px solid var(--sr-border, #E2E8F0)',
                          bgcolor: 'var(--sr-surface-raised, #F8FAFC)',
                          display: 'flex',
                          flexDirection: { xs: 'column', sm: 'row' },
                          justifyContent: 'space-between',
                          alignItems: { xs: 'flex-start', sm: 'center' },
                          gap: 1.5
                        }}
                      >
                        <Box>
                          <Typography variant="subtitle2" sx={{ fontWeight: 800, color: 'var(--sr-text, #0F172A)' }}>
                            {labels[row.type]}
                          </Typography>
                          <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 0.2 }}>
                            Expiry Date: <span style={{ fontFamily: 'var(--sr-font-mono, monospace)', fontWeight: 600 }}>{expiry.toLocaleDateString()}</span>
                          </Typography>
                          {row.notes && (
                            <Typography variant="caption" sx={{ color: 'text.secondary', fontStyle: 'italic', display: 'block', mt: 0.2 }}>
                              Note: {row.notes}
                            </Typography>
                          )}
                        </Box>

                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, alignSelf: { xs: 'flex-end', sm: 'center' } }}>
                          {/* Verification Chip */}
                          <Chip
                            label={String(row.status).toUpperCase()}
                            size="small"
                            sx={{
                              fontSize: 10,
                              fontWeight: 700,
                              letterSpacing: '0.04em',
                              height: 22,
                              bgcolor: row.status === 'verified' ? 'rgba(5, 150, 105, 0.1)' : 'rgba(0,0,0,0.06)',
                              color: row.status === 'verified' ? 'var(--sr-emerald)' : 'text.secondary'
                            }}
                          />

                          {/* Countdown Chip */}
                          <Chip
                            label={countdownLabel}
                            size="small"
                            sx={{
                              fontWeight: 700,
                              fontSize: 11,
                              fontFamily: 'var(--sr-font-mono, monospace)',
                              bgcolor: countdownBg,
                              color: countdownColor,
                              border: `1px solid ${countdownBorder}`,
                              height: 24,
                              borderRadius: '6px'
                            }}
                          />
                        </Box>
                      </Box>
                    )
                  })}
                </Box>
              )}
            </CardContent>
          </Card>
        </Box>
      </div>
    </Layout>
  )
}

export default VehicleDocuments
